# Cell
def find_peak(y, times=2):
    # ys = smooth1d_fft(np.arange(len(y)), y, 120)
    # ys = ndimage.gaussian_filter1d(y,10)
    ys = get_baseline(None, y, axis=-1, method='arPLS',
                      bl_para={'lam': 1e5, 'deg': 3, 'niter': 1})
    s, m, e = np.nanpercentile(y-ys, [16, 50, 84], axis=-1)
    is_ = (ys < m-(m-s)*times) | (ys > m+(e-m)*times)
    return is_, ys

# Cell
def get_ref_ind_otf(ra, dec, scan_dir):
    if scan_dir.lower() in ['-', 'dec']:
        is_, _ = find_peak(np.diff(dec), 2)
    elif scan_dir.lower() in ['|', 'ra']:
        is_, _ = find_peak(np.diff(ra), 2)
    ind_ref = np.arange(len(ra))[1:][is_]
    return ind_ref

