# Cell
class IO(BaseIO):
    ver = 'old'

    def _get_fpart(self,):
        """
        need modify this function
        """
        fpart = '-sub_ref'
        return fpart

    def gen_s2p_out(self,):
        args = self.args
        s2p = self.s2p[:]

        if args.mode.lower() == 'otf':
            ra, dec = self.ra, self.dec
            ra = _tight_ra(ra)
            # find reference spectra
            ind_ref = get_ref_ind_otf(ra, dec, args.scan_dir)
            # use the nearest reference
            ind_all = ind_ref[np.argmin(abs(np.arange(len(ra))[:, None] - ind_ref[None, :]), axis=1)]
            s2p = s2p - s2p[ind_all]
        elif args.mode.lower() == 'drift':
            s2p = s2p - np.mean(s2p[:5], axis=0)[None,:]

        self.s2p_out = s2p

